import {supabase} from './cloud.js';
import {clone,normalize,uid} from './domain.js';
export async function rpc(name,args={}){const {data,error}=await supabase.rpc(name,args);if(error)throw Error(error.message);return data}
export async function query(table,filter){const rows=[];for(let offset=0;;offset+=1000){let q=supabase.from(table).select('*');if(filter)for(const [k,v]of Object.entries(filter))q=q.eq(k,v);const {data,error}=await q.range(offset,offset+999);if(error)throw Error(error.message);rows.push(...data);if(data.length<1000)return rows;}}
export async function initialize(){const workspaceId=await rpc('ensure_workspace');const workspaces=await query('workspaces');return {workspaceId,workspaces}}
export async function fetchGuides(){const rows=await query('guides'),steps=await query('guide_steps');return rows.map(r=>({...r.body,id:r.id,workspaceId:r.workspace_id,revision:r.revision,updatedAt:r.updated_at,dirty:false,steps:steps.filter(s=>s.guide_id===r.id).sort((a,b)=>a.position-b.position).map(s=>s.body)}))}
export async function legacyGuides(userId,w){const rows=await query('workflow_libraries',{user_id:userId});return (rows[0]?.workflows||[]).map(g=>({...normalize(g,w),sourceId:g.id,revision:0,dirty:true}))}
export async function hydrate(document){const doc=clone(document);for(const s of doc.steps)for(const field of ['screenshot','audio','video']){if(s[field+'Path']&&!s[field]){const {data,error}=await supabase.storage.from('guide-assets').download(s[field+'Path']);if(error)throw Error(error.message);s[field]=await blobData(data)}}return doc}
export function blobData(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
async function upload(doc,step,field){const value=step[field];if(!value?.startsWith('data:'))return;const blob=await (await fetch(value)).blob();const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()))).map(v=>v.toString(16).padStart(2,'0')).join('');const path=`${doc.workspaceId}/${doc.id}/${digest}`;
 const {error}=await supabase.storage.from('guide-assets').upload(path,blob,{contentType:blob.type,upsert:false});if(error&&error.statusCode!=='409'&&error.statusCode!==409&&!/already exists/i.test(error.message))throw Error(error.message);step[field+'Path']=path;delete step[field];}
export async function syncGuide(document){const doc=clone(document);for(const s of doc.steps){delete s.original;delete s.imageHistory;for(const field of ['screenshot','audio','video'])await upload(doc,s,field)}delete doc.dirty;delete doc.localOnly;const revision=await rpc('save_guide',{document:doc,expected_revision:document.revision||0});return {revision,paths:doc.steps};}
export async function deleteCloudGuide(doc){if(!doc.revision)return;for(;;){const {data,error}=await supabase.storage.from('guide-assets').list(`${doc.workspaceId}/${doc.id}`,{limit:1000});if(error)throw Error(error.message);if(!data.length)break;const {error:e}=await supabase.storage.from('guide-assets').remove(data.map(x=>`${doc.workspaceId}/${doc.id}/${x.name}`));if(e)throw Error(e.message)}await rpc('delete_guide',{g:doc.id});}
export async function publish(doc,settings){const snapshot=await hydrate(doc);for(const s of snapshot.steps){delete s.original;delete s.imageHistory;delete s.screenshotPath;delete s.audioPath;delete s.videoPath;}return rpc('publish_guide',{g:doc.id,snapshot,passphrase:settings.password||'',expiry:settings.expiry||null,domain:settings.domain||null})}
